@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>@WarehouseState.SelectedWarehouseName</strong>
    </div>
    <div class="card-body">
        <h5 class="card-title">Inventory Alerts</h5>
        <p class="card-text">
            Items below minimum stock level:
            <span class="badge @(AlertService.LowStockCount > 0 ? "bg-danger" : "bg-success") fs-5">
                @AlertService.LowStockCount
            </span>
        </p>
        <p class="text-muted">
            <small>Auto-refreshes every 10 seconds. Last checked: @_lastRefresh.ToString("HH:mm:ss")</small>
        </p>
    </div>
</div>

<div class="alert alert-info">
    <strong>How it works:</strong> This page starts polling when you navigate here and stops when you leave.
    The sidebar badge also updates in real-time because both components subscribe to the same
    <code>InventoryAlertService.OnAlertCountChanged</code> event. Switching warehouses in the
    top bar immediately triggers a refresh for all subscribers.
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;
    private DateTime _lastRefresh = DateTime.Now;

    protected override void OnInitialized()
    {
        // Subscribe to warehouse changes
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;

        // Subscribe to alert data changes
        _alertHandler = () => InvokeAsync(() =>
        {
            _lastRefresh = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertCountChanged += _alertHandler;

        // Start polling while this page is visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.StopPolling();
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

